def facts():return deepcopy(EXPECTED)

def validate_contract(contract=None,source_bindings=None):
    actual=strict_json(PATH.read_bytes()) if contract is None else deepcopy(contract)
    oracle._equal(actual,facts(),'contract/independent_closed_facts')
    supplied={r['path']:r for r in source_bindings} if source_bindings is not None else None
    for row in EXPECTED['sourceBindings']:
        raw=(ROOT/row['path']).read_bytes()
        if (len(raw),sha256(raw).hexdigest())!=(row['bytes'],row['sha256']):
            raise ValueError('ReviewedSelectorSemanticSourceChanged:'+row['path'])
        if supplied is not None and (row['path'] not in supplied or any(supplied[row['path']][k]!=row[k] for k in ('bytes','sha256'))):
            raise ValueError('CurrentSourceJoinMissingReviewedBinding:'+row['path'])
    cases=list(corpus.iter_cases());coverage=corpus.coverage(cases)
    oracle._equal((coverage['cases'],coverage['retirements'],coverage['selectorCounts']),(16,784,{0:4,1:4,2:4,3:4}),'contract/independent_16_784_4each')
    expected=[oracle.expected_case(c) for c in cases]
    oracle._equal(sum(e['instruction_count'] for e in expected),784,'contract/full49_models')
    oracle._equal(sum(e['history0128_rmw'][-1]['same_value'] for e in expected),8,'contract/eight_same_value_sbr_writers')
    oracle._equal(sum(e['selector_initial']==3 and e['selector_final']==0 for e in expected),4,'contract/four_wrap_controls')
    for e in expected:
        oracle._equal(len(e['steps']),49,'contract/exact49')
        oracle._equal(len([r for r in e['all_native_journal'] if r[4]==1]),19,'contract/19_all_native_writes')
        oracle._equal(e['selector_generation']['logical_write_ordinal'],76,'contract/selector_logical76')
        oracle._equal(e['selector_generation']['raw_write_ordinal'],113,'contract/selector_raw113')
    identity=oracle.public_program_identity()
    oracle._equal(len(identity['selected_extent_sha256']),59,'contract/independent59sites')
    return {'schemaVersion':1,'milestone':'M2bz','passed':True,'classification':'IndependentStaticPostReturnSelectorContract_NotRuntimeEvidence',
        'casesPerDomain':16,'retirementsPerDomain':784,'publicProgramSha256':identity['program_sha256'],
        'actualCpuExecutions':0,'nativeNextEventSelectorHandoffVerified':False,'firmwareReady':False}
